<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { addProfileRolesBatch, syncProfileRoles } from "../api";
import type { Profile, Role } from "../api/contracts";
import DataPanel from "../components/DataPanel.vue";
import Icon from "../components/Icon.vue";
import { useMutation } from "../composables/useMutation";
import { useCatalogsStore } from "../stores/catalogs";

const catalogs = useCatalogsStore(), route = useRoute(), router = useRouter();
const profileId = ref(String(route.query.profileId || ""));
const mode = ref<"add" | "edit">("edit"), query = ref(""), scope = ref("");
const page = ref(1), selected = ref(new Set<string>());
const draggingId = ref<string | null>(null), dragOver = ref<"available" | "assigned" | null>(null);
const { busy, error, run } = useMutation();
const pageSize = ref(20);
const profile = computed<Profile | undefined>(() => catalogs.profiles.find(item => item.id === profileId.value));
const savedRoleIds = computed(() => new Set(profile.value?.roleIds || []));
const compatibleRoles = computed(() => catalogs.roles.filter(role => role.scope !== "GLOBAL" &&
  (profile.value?.scope === "TENANT"
    ? role.scope === "TENANT"
    : role.scope === "TENANT" || role.applicationId === profile.value?.applicationId)));
const availableRoles = computed(() => compatibleRoles.value.filter(role =>
  (!query.value || role.name.toLowerCase().includes(query.value.toLowerCase())) && (!scope.value || role.scope === scope.value) &&
  (mode.value === "edit" || !profile.value?.roleIds.includes(role.id))));
const totalPages = computed(() => Math.max(1, Math.ceil(availableRoles.value.length / pageSize.value)));
const visibleRoles = computed(() => availableRoles.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value));
const visibleAvailableRoles = computed(() => visibleRoles.value.filter(role => !selected.value.has(role.id)));
const visibleAssignedRoles = computed(() => visibleRoles.value.filter(role => selected.value.has(role.id)));
const groupedCount = computed(() => compatibleRoles.value.filter(role => selected.value.has(role.id)).length);
const coverage = computed(() => compatibleRoles.value.length ? Math.round((groupedCount.value / compatibleRoles.value.length) * 100) : 0);
const allVisibleSelected = computed(() => visibleRoles.value.length > 0 && visibleRoles.value.every(role => selected.value.has(role.id)));
function reset() { selected.value = new Set(mode.value === "edit" ? profile.value?.roleIds || [] : []); }
function toggle(id: string) { const next = new Set(selected.value); next.has(id) ? next.delete(id) : next.add(id); selected.value = next; }
function togglePage() { const next = new Set(selected.value); (allVisibleSelected.value ? visibleRoles.value.forEach(role => next.delete(role.id)) : visibleRoles.value.forEach(role => next.add(role.id))); selected.value = next; }
function assign(id: string) { if (selected.value.has(id)) return; const next = new Set(selected.value); next.add(id); selected.value = next; }
function unassign(id: string) { if (!selected.value.has(id)) return; const next = new Set(selected.value); next.delete(id); selected.value = next; }
function startDrag(event: DragEvent, id: string) {
  draggingId.value = id;
  dragOver.value = null;
  event.dataTransfer?.setData("text/plain", id);
  if (event.dataTransfer) {
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setDragImage(event.currentTarget as HTMLElement, 18, 18);
  }
}
function endDrag() { draggingId.value = null; dragOver.value = null; }
function enterDrop(zone: "available" | "assigned", event: DragEvent) { if (!draggingId.value) return; event.preventDefault(); if (event.dataTransfer) event.dataTransfer.dropEffect = "move"; dragOver.value = zone; }
function leaveDrop(zone: "available" | "assigned", event: DragEvent) { const current = event.currentTarget as HTMLElement | null, next = event.relatedTarget as Node | null; if (current && next && current.contains(next)) return; if (dragOver.value === zone) dragOver.value = null; }
function dropOn(zone: "available" | "assigned", event: DragEvent) { event.preventDefault(); const id = draggingId.value || event.dataTransfer?.getData("text/plain") || ""; if (id) zone === "assigned" ? assign(id) : unassign(id); endDrag(); }
async function save() {
  if (!profile.value) return;
  const data = { roleIds: [...selected.value] };
  if (mode.value === "add" && !data.roleIds.length) return;
  const message = mode.value === "add" ? "Los roles seleccionados fueron agregados al perfil." : "Los roles del perfil fueron actualizados.";
  if (await run(() => mode.value === "add" ? addProfileRolesBatch(profile.value!.id, data) : syncProfileRoles(profile.value!.id, data), message)) { mode.value = "edit"; reset(); }
}
watch([profileId, mode], () => { page.value = 1; reset(); });
watch([query, scope], () => page.value = 1);
watch(pageSize, () => page.value = 1);
watch(totalPages, () => { if (page.value > totalPages.value) page.value = totalPages.value; });
watch(() => catalogs.profiles, profiles => { if (!profiles.some(item => item.id === profileId.value)) profileId.value = profiles[0]?.id || ""; }, { immediate: true });
</script>
<template>
  <DataPanel title="Gestor de roles" :count="availableRoles.length" empty="No hay roles que coincidan con los filtros." show-content-when-empty>
    <div class="profile-context">
      <button class="back" type="button" @click="router.push({ name: 'profiles' })"><span aria-hidden="true">←</span> Volver al catálogo de perfiles</button>
      <div class="profile-context-grid">
        <label class="profile-field"><span>Perfil</span><select v-model="profileId"><option v-for="item in catalogs.profiles.filter(item => item.scope !== 'GLOBAL')" :key="item.id" :value="item.id">{{ item.name }} · {{ item.scope === 'TENANT' ? 'Tenant' : 'Aplicación' }}</option></select></label>
        <div v-if="profile" class="profile-card">
          <div class="profile-card-top"><span :class="['scope-pill', `scope-${profile.scope.toLowerCase()}`]"><Icon name="layers" :size="12" />{{ profile.scope === 'TENANT' ? 'Tenant' : 'Aplicación' }}</span><span class="profile-count">{{ groupedCount }}/{{ compatibleRoles.length }}</span></div>
          <strong :title="profile.name">{{ profile.name }}</strong>
          <div class="profile-meter" role="progressbar" :aria-valuenow="coverage" aria-valuemin="0" aria-valuemax="100" :aria-label="`Cobertura de roles del perfil ${profile.name}`"><i :style="{ width: `${coverage}%` }" /></div>
          <small>{{ groupedCount }} de {{ compatibleRoles.length }} roles compatibles agrupados</small>
        </div>
      </div>
    </div>
    <div class="profile-body">
      <p class="profile-help"><Icon name="layers" :size="15" />{{ mode === 'add' ? 'Selecciona roles compatibles para agregarlos al perfil sin retirar asociaciones actuales.' : 'Selecciona los roles que debe agrupar el perfil y guarda los cambios.' }}</p>
      <p v-if="error" class="profile-alert" role="alert"><Icon name="close" :size="14" />{{ error }}</p>
      <div class="profile-toolbar">
        <label class="profile-search"><Icon name="search" :size="16" /><input v-model="query" placeholder="Buscar por nombre" aria-label="Buscar roles" /><button v-if="query" type="button" aria-label="Limpiar búsqueda" @click="query = ''">×</button></label>
        <div class="scope-filters" aria-label="Filtrar por alcance"><button :class="{on: !scope}" @click="scope = ''">Todos</button><button :class="{on: scope === 'TENANT'}" @click="scope = 'TENANT'">Tenant</button><button :class="{on: scope === 'APPLICATION'}" @click="scope = 'APPLICATION'">Aplicación</button></div>
        <button class="select-page" type="button" :disabled="!visibleRoles.length" @click="togglePage"><Icon name="check" :size="14" />{{ allVisibleSelected ? 'Quitar visibles' : 'Seleccionar visibles' }}</button>
      </div>
      <div class="profile-board" :aria-busy="busy">
        <section class="profile-column" :class="{ 'drop-active': draggingId && dragOver === 'available' }" @dragenter.prevent="enterDrop('available', $event)" @dragover.prevent="enterDrop('available', $event)" @dragleave="leaveDrop('available', $event)" @drop.prevent="dropOn('available', $event)">
          <header class="profile-column-head"><div class="profile-column-title"><span class="profile-column-icon"><Icon name="layers" :size="15" /></span><div><div class="profile-column-line"><h3>Disponibles</h3><span>{{ visibleAvailableRoles.length }}</span></div><p>{{ draggingId && dragOver === 'available' ? 'Suelta aquí para retirar el rol' : 'Arrastra al panel derecho para agregar' }}</p></div></div><button v-if="visibleAvailableRoles.length" type="button" @click="visibleAvailableRoles.forEach(role => assign(role.id))">Agregar visibles</button></header>
          <div class="profile-list" role="list" aria-label="Roles disponibles"><article v-for="role in visibleAvailableRoles" :key="role.id" class="profile-role-card" :class="{ 'is-dragging': draggingId === role.id, 'pending-removal': savedRoleIds.has(role.id) }" role="listitem" draggable="true" @dragstart="startDrag($event, role.id)" @dragend="endDrag"><span class="profile-grip"><Icon name="grip" :size="14" /></span><div class="profile-role-copy"><div class="profile-role-meta"><span :class="['scope-pill', `scope-${role.scope.toLowerCase()}`]"><Icon name="key" :size="12" />{{ role.scope === 'TENANT' ? 'Tenant' : 'Aplicación' }}</span><span v-if="savedRoleIds.has(role.id)" class="profile-tag removed">Se retira</span></div><strong>{{ role.name }}</strong><small>{{ role.applicationId ? catalogs.appById[role.applicationId]?.name || role.applicationId : 'Disponible en el tenant' }}</small></div><button class="profile-move" type="button" :aria-label="`Agregar ${role.name} al perfil`" @click="assign(role.id)"><Icon name="arrow" :size="14" /></button></article><p v-if="!visibleAvailableRoles.length" class="roles-empty"><Icon name="check" :size="20" /><strong>Sin roles disponibles</strong><span>Arrastra aquí un rol para retirarlo del perfil.</span></p></div>
        </section>
        <section class="profile-column assigned" :class="{ 'drop-active': draggingId && dragOver === 'assigned' }" @dragenter.prevent="enterDrop('assigned', $event)" @dragover.prevent="enterDrop('assigned', $event)" @dragleave="leaveDrop('assigned', $event)" @drop.prevent="dropOn('assigned', $event)">
          <header class="profile-column-head"><div class="profile-column-title"><span class="profile-column-icon"><Icon name="check" :size="15" /></span><div><div class="profile-column-line"><h3>Roles del perfil</h3><span>{{ visibleAssignedRoles.length }}</span></div><p>{{ draggingId && dragOver === 'assigned' ? 'Suelta aquí para agregar el rol' : 'Arrastra al panel izquierdo para retirar' }}</p></div></div><button v-if="visibleAssignedRoles.length" type="button" @click="visibleAssignedRoles.forEach(role => unassign(role.id))">Retirar visibles</button></header>
          <div class="profile-list" role="list" aria-label="Roles agrupados en el perfil"><article v-for="role in visibleAssignedRoles" :key="role.id" class="profile-role-card assigned-card" :class="{ 'is-dragging': draggingId === role.id, 'pending-add': !savedRoleIds.has(role.id) }" role="listitem" draggable="true" @dragstart="startDrag($event, role.id)" @dragend="endDrag"><span class="profile-grip"><Icon name="grip" :size="14" /></span><div class="profile-role-copy"><div class="profile-role-meta"><span :class="['scope-pill', `scope-${role.scope.toLowerCase()}`]"><Icon name="key" :size="12" />{{ role.scope === 'TENANT' ? 'Tenant' : 'Aplicación' }}</span><span class="profile-tag" :class="savedRoleIds.has(role.id) ? 'active' : 'new'">{{ savedRoleIds.has(role.id) ? 'Asignado' : 'Nuevo' }}</span></div><strong>{{ role.name }}</strong><small>{{ role.applicationId ? catalogs.appById[role.applicationId]?.name || role.applicationId : 'Disponible en el tenant' }}</small></div><button class="profile-move back" type="button" :aria-label="`Retirar ${role.name} del perfil`" @click="unassign(role.id)"><Icon name="arrow" :size="14" /></button></article><p v-if="!visibleAssignedRoles.length" class="roles-empty"><Icon name="layers" :size="20" /><strong>Aún no hay roles agrupados</strong><span>Arrastra un rol aquí o usa la flecha para agregarlo.</span></p></div>
        </section>
      </div>
    </div>
    <footer class="profile-footer"><span>{{ availableRoles.length }} roles · {{ selected.size }} seleccionados</span><div class="pagination"><label>Mostrar <select v-model.number="pageSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button :disabled="page===1" @click="page--">Anterior</button><span>Página {{ page }} de {{ totalPages }}</span><button :disabled="page===totalPages" @click="page++">Siguiente</button></div><button class="create-action save-action" :disabled="busy || !profileId || (mode === 'add' && !selected.size)" @click="save"><Icon name="check" :size="15" />{{ busy ? 'Guardando…' : mode === 'add' ? 'Agregar seleccionados' : 'Guardar roles' }}</button></footer>
  </DataPanel>
</template>
