.profile-context { display:grid; gap:15px; padding:18px 26px 20px; border-bottom:1px solid var(--soft-line); background:linear-gradient(180deg,#fbfcfb,var(--paper)); }.back { justify-self:start; display:inline-flex; gap:7px; align-items:center; padding:3px 0; border:0; background:none; color:var(--green-ink); font-size:12px; font-weight:600; }.back span { font-size:17px; }.back:hover { color:var(--green); }.profile-context-grid { display:grid; grid-template-columns:minmax(190px,1fr) minmax(200px,.95fr) auto; gap:14px; align-items:end; }.profile-field { display:grid; gap:6px; min-width:0; }.profile-field > span { color:var(--faint); font:500 10px 'IBM Plex Mono',monospace; letter-spacing:.1em; text-transform:uppercase; }.profile-field select { width:100%; height:42px; min-width:0; padding:0 11px; border:1px solid var(--line); border-radius:7px; background:var(--field); color:var(--ink); font-size:13px; }.profile-card { display:grid; gap:5px; min-width:0; padding:10px 12px; border:1px solid rgba(1,139,81,.18); border-radius:9px; background:var(--green-tint); }.profile-card > div { display:flex; justify-content:space-between; align-items:center; gap:8px; }.profile-card .scope-pill { padding:3px 7px; font-size:9px; }.profile-count { color:var(--green-ink); font:500 11px 'IBM Plex Mono',monospace; }.profile-card strong { overflow:hidden; font-size:13px; text-overflow:ellipsis; white-space:nowrap; }.profile-card small { color:var(--green-ink); font-size:10px; }.mode { display:flex; align-self:stretch; border:1px solid var(--line); border-radius:7px; overflow:hidden; }.mode button { min-width:90px; border:0; background:var(--paper); color:var(--text); font-size:11px; }.mode .active { background:var(--green); color:#fff; }.profile-body { display:grid; gap:14px; padding:18px 26px 20px; }.profile-help,.profile-alert { display:flex; gap:8px; align-items:flex-start; margin:0; padding:10px 12px; border-radius:7px; font-size:12px; line-height:1.45; }.profile-help { color:var(--te