; height:18px; place-items:center; border-radius:999px; background:var(--green); color:#fff; font:600 10px 'IBM Plex Mono',monospace; }.profile-drop-zone.drop-active { border-style:solid; border-color:var(--green); box-shadow:0 0 0 3px rgba(1,139,81,.12); background:var(--green-wash); }.profile-role-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(min(100%,235px),1fr)); gap:10px; }.profile-role-card { display:grid; grid-template-columns:16px minmax(0,1fr) 16px; gap:9px; align-items:start; min-height:112px; padding:12px; border:1px solid var(--line); border-radius:9px; background:var(--paper); cursor:grab; transition:.16s ease; }.profile-role-card:active { cursor:grabbing; }.profile-role-card.is-dragging { border-style:dashed; opacity:.42; }.profile-role-card:hover { border-color:rgba(1,139,81,.35); box-shadow:0 2px 8px rgba(17,19,18,.045); }.profile-role-card.selected { border-color:rgba(1,139,81,.45); background:var(--green-tint); }.profile-role-card input { margin-top:4px; accent-color:var(--green); }.profile-role-copy { display:grid; gap:7px; min-width:0; }.profile-role-copy .scope-pill { width:max-content; padding:3px 7px; font-size:9px; }.profile-role-copy strong { overflow:hidden; color:var(--ink); font-size:13px; text-overflow:ellipsis; white-space:nowrap; }.profile-role-copy small { overflow:hidden; color:var(--faint); font-size:11px; text-overflow:ellipsis; white-space:nowrap; }.selected-icon { margin-top:3px; color:var(--green); opacity:0; }.selected .selected-icon { opacity:1; }.roles-empty { display:grid; grid-column:1 / -1; justify-items:center; gap:5px; margin:0; padding:28px; border:1px dashed var(--line); border-radius:9px; color:var(--faint); font-size:11px; text-align:center; }.roles-empty svg { color:var(--green); }.roles-empty strong { color:var(--ink); font-size:12px; }.profile-footer { display:flex; flex-wrap:wrap; gap:14px; align-items:center; justify-content:space-between; padding:15px 26px; border-top:1px solid var(--soft-l