ursor:grab; }.profile-column .profile-role-card:active { cursor:grabbing; }.profile-column .profile-role-card.assigned-card { border-color:rgba(1,139,81,.3); background:var(--green-tint); }.profile-column .profile-role-card.pending-removal { border-color:rgba(185,61,60,.28); background:rgba(185,61,60,.025); }.profile-column .profile-role-card.pending-add { border-color:rgba(1,139,81,.34); background:var(--green-tint); }.profile-grip { display:grid; place-items:center; color:#c0c7c2; }.profile-role-card:hover .profile-grip { color:var(--faint); }.profile-column .profile-role-copy { gap:5px; }.profile-column .profile-role-copy .scope-pill { font-size:8px; }.profile-tag { width:max-content; padding:3px 6px; border-radius:999px; font:600 9px 'IBM Plex Mono',monospace; letter-spacing:.06em; text-transform:uppercase; }.profile-tag.active { background:var(--green-wash); color:var(--green-ink); }.profile-tag.new { background:rgba(1,139,81,.15); color:var(--green-ink); }.profile-tag.removed { background:rgba(185,61,60,.09); color:var(--red); }.profile-move { display:grid; width:29px; height:29px; place-items:center; border:1px solid var(--line); border-radius:6px; background:var(--paper); color:var(--text); transition:.16s ease; }.profile-move:hover { border-color:var(--green); background:var(--green); color:#fff; }.profile-move.back svg { transform:rotate(180deg); }.profile-move.back:hover { border-color:rgba(185,61,60,.5); background:rgba(185,61,60,.08); color:var(--red); }.profile-column .roles-empty { min-height:180px; margin:auto 0; }.profile-column .roles-empty span { max-width:210px; }.profile-column .profile-role-card.is-dragging { border-style:dashed; opacity:.42; }
.profile-column .profile-role-card { flex:0 0 92px; min-height:92px; }
